1	<?php
2	
3	namespace App\Http\Controllers\Api\Webhooks;
4	
5	use App\Http\Controllers\Controller;
6	use App\Models\Billing\Plan;
7	use App\Models\Billing\Subscription;
8	use App\Models\Core\Professional\Professional;
9	use App\Services\Notifications\NotificationPublisher;
10	use App\Services\Professional\SiteProvisioningService;
11	use Carbon\Carbon;
12	use Illuminate\Http\JsonResponse;
13	use Illuminate\Http\Request;
14	use Illuminate\Support\Facades\DB;
15	use Illuminate\Support\Facades\Log;
16	use Illuminate\Support\Str;
17	use Stripe\Exception\SignatureVerificationException;
18	use Stripe\Webhook;
19	
20	// V2: Core. Processes Stripe Billing subscription lifecycle webhooks. Source of truth for subscription state.
21	class StripeWebhookController extends Controller
22	{
23	    use ValidatesStripeWebhookPayload;
24	    public function __invoke(Request $request): JsonResponse
25	    {
26	        $payload = $request->getContent();
27	        $sigHeader = $request->header('Stripe-Signature');
28	
29	        if (! $sigHeader) {
30	            return response()->json(['error' => 'Missing signature'], 400);
31	        }
32	
33	        $secret = config('services.stripe.webhook_secret');
34	
35	        if (! $secret) {
36	            return response()->json(['error' => 'No webhook secret configured'], 400);
37	        }
38	
39	        try {
40	            $event = Webhook::constructEvent($payload, $sigHeader, $secret);
41	        } catch (SignatureVerificationException) {
42	            Log::warning('Stripe billing webhook signature verification failed');
43	
44	            return response()->json(['error' => 'Invalid signature'], 400);
45	        } catch (\Exception $e) {
46	            Log::warning('Stripe billing webhook parse error', ['error' => $e->getMessage()]);
47	
48	            return response()->json(['error' => 'Invalid payload'], 400);
49	        }
50	
51	        if (! $this->validateEventStructure($event)) {
52	            return response()->json(['error' => 'Invalid payload structure'], 400);
53	        }
54	
55	        // Idempotency: atomic insert-or-skip using DB unique constraint on stripe_event_id.
56	        // This prevents race conditions where two concurrent requests pass an exists() check.
57	        $alreadyProcessed = ! DB::table('billing.webhook_events')->insertOrIgnore([
58	            'id' => Str::uuid()->toString(),
59	            'stripe_event_id' => $event->id,
60	            'event_type' => $event->type,
61	            'payload' => json_encode(json_decode($payload, true)),
62	            'processed_at' => now(),
63	        ]);
64	
65	        if ($alreadyProcessed) {
66	            return response()->json(['received' => true]);
67	        }
68	
69	        match ($event->type) {
70	            'customer.subscription.created' => $this->handleSubscriptionCreated($event->data->object, $event),
71	            'customer.subscription.updated' => $this->handleSubscriptionUpdated($event->data->object, $event),
72	            'customer.subscription.deleted' => $this->handleSubscriptionDeleted($event->data->object, $event),
73	            'invoice.paid' => $this->handleInvoicePaid($event->data->object, $event),
74	            'invoice.payment_failed' => $this->handleInvoicePaymentFailed($event->data->object, $event),
75	            'payment_method.detached' => $this->handlePaymentMethodDetached($event->data->object),
76	            default => Log::debug('Unhandled Stripe billing event', ['type' => $event->type]),
77	        };
78	
79	        return response()->json(['received' => true]);
80	    }
81	
82	    private function handleSubscriptionCreated(object $subscription, object $event): void
83	    {
84	        // Resolve professional: prefer stripe_customer_id lookup (tamper-proof),
85	        // fall back to metadata (set server-side by StripeBillingService).
86	        $stripeCustomerId = (string) ($subscription->customer ?? '');
87	        $professional = $stripeCustomerId
88	            ? Professional::where('stripe_customer_id', $stripeCustomerId)->first()
89	            : null;
90	
91	        if (! $professional) {
92	            $professionalId = $subscription->metadata?->sidest_professional_id ?? null;
93	            $professional = $professionalId ? Professional::find($professionalId) : null;
94	        }
95	
96	        if (! $professional) {
97	            Log::warning('Stripe subscription.created: could not resolve professional', [
98	                'subscription_id' => $subscription->id,
99	                'customer_id' => $stripeCustomerId,
100	                'metadata_professional_id' => $subscription->metadata?->sidest_professional_id ?? null,
101	            ]);
102	
103	            return;
104	        }
105	
106	        $priceId = $subscription->items->data[0]->price->id ?? null;
107	        $plan = Plan::where('stripe_price_id', $priceId)->where('is_active', true)->first();
108	
109	        if (! $plan) {
110	            Log::error('Stripe subscription.created with unknown price — customer charged but no local subscription created. Manual reconciliation required.', [
111	                'price_id' => $priceId,
112	                'professional_id' => $professional->id,
113	                'stripe_subscription_id' => $subscription->id,
114	            ]);
115	
116	            return;
117	        }
118	
119	        DB::transaction(function () use ($professional, $plan, $subscription, $event) {
120	            // End any existing active subscription (lockForUpdate prevents deadlocks)
121	            Subscription::query()
122	                ->where('professional_id', $professional->id)
123	                ->whereNull('ended_at')
124	                ->lockForUpdate()
125	                ->update(['ended_at' => now()]);
126	
127	            // Create the new Stripe-managed subscription; stripe IDs set directly (not mass-assignable)
128	            $localSub = new Subscription([
129	                'id' => Str::uuid()->toString(),
130	                'professional_id' => $professional->id,
131	                'plan_id' => $plan->id,
132	                'provider' => 'stripe',
133	                'status' => $this->mapStripeStatus($subscription->status),
134	                'current_period_start' => Carbon::createFromTimestamp($subscription->current_period_start),
135	                'current_period_end' => Carbon::createFromTimestamp($subscription->current_period_end),
136	                'cancel_at_period_end' => $subscription->cancel_at_period_end ?? false,
137	                'provider_payload' => json_decode(json_encode($event), true),
138	            ]);
139	            $localSub->stripe_customer_id = (string) $subscription->customer;
140	            $localSub->stripe_subscription_id = (string) $subscription->id;
141	            $localSub->save();
142	        });
143	
144	        Log::info('Stripe subscription created', [
145	            'professional_id' => $professional->id,
146	            'plan_key' => $plan->plan_key,
147	            'stripe_subscription_id' => $subscription->id,
148	        ]);
149	    }
150	
151	    private function handleSubscriptionUpdated(object $subscription, object $event): void
152	    {
153	        $localSub = Subscription::where('stripe_subscription_id', $subscription->id)->first();
154	
155	        if (! $localSub) {
156	            Log::debug('Stripe subscription.updated for unknown subscription', [
157	                'stripe_subscription_id' => $subscription->id,
158	            ]);
159	
160	            return;
161	        }
162	
163	        $updates = [
164	            'status' => $this->mapStripeStatus($subscription->status),
165	            'current_period_start' => Carbon::createFromTimestamp($subscription->current_period_start),
166	            'current_period_end' => Carbon::createFromTimestamp($subscription->current_period_end),
167	            'cancel_at_period_end' => $subscription->cancel_at_period_end ?? false,
168	            'provider_payload' => json_decode(json_encode($event), true),
169	        ];
170	
171	        // Check if price changed (plan upgrade/downgrade)
172	        $priceId = $subscription->items->data[0]->price->id ?? null;
173	        if ($priceId) {
174	            $plan = Plan::where('stripe_price_id', $priceId)->where('is_active', true)->first();
175	            if ($plan && $plan->id !== $localSub->plan_id) {
176	                $updates['plan_id'] = $plan->id;
177	            }
178	        }
179	
180	        $localSub->update($updates);
181	
182	        Log::info('Stripe subscription updated', [
183	            'subscription_id' => $localSub->id,
184	            'status' => $updates['status'],
185	        ]);
186	    }
187	
188	    private function handleSubscriptionDeleted(object $subscription, object $event): void
189	    {
190	        $localSub = Subscription::where('stripe_subscription_id', $subscription->id)->first();
191	
192	        if (! $localSub) {
193	            Log::debug('Stripe subscription.deleted for unknown subscription', [
194	                'stripe_subscription_id' => $subscription->id,
195	            ]);
196	
197	            return;
198	        }
199	
200	        $localSub->update([
201	            'status' => Subscription::STATUS_CANCELED,
202	            'ended_at' => now(),
203	            'provider_payload' => json_decode(json_encode($event), true),
204	        ]);
205	
206	        // For affiliates, fall back to free plan. Brands do NOT get a free fallback.
207	        $professional = $localSub->professional;
208	        if ($professional && $professional->professional_type !== 'brand') {
209	            app(SiteProvisioningService::class)->ensureFreeSubscription($professional);
210	        }
211	
212	        Log::info('Stripe subscription deleted', [
213	            'subscription_id' => $localSub->id,
214	            'professional_id' => $localSub->professional_id,
215	            'fallback_to_free' => $professional?->professional_type !== 'brand',
216	        ]);
217	    }
218	
219	    private function handleInvoicePaid(object $invoice, object $event): void
220	    {
221	        $stripeSubId = $invoice->subscription ?? null;
222	        if (! $stripeSubId) {
223	            return;
224	        }
225	
226	        $localSub = Subscription::where('stripe_subscription_id', $stripeSubId)->first();
227	        if (! $localSub) {
228	            return;
229	        }
230	
231	        $updates = [
232	            'provider_payload' => json_decode(json_encode($event), true),
233	        ];
234	
235	        // Reset to active if was past_due (successful retry)
236	        if ($localSub->status === Subscription::STATUS_PAST_DUE) {
237	            $updates['status'] = Subscription::STATUS_ACTIVE;
238	        }
239	
240	        // Update period dates from invoice
241	        if (isset($invoice->lines->data[0]->period)) {
242	            $period = $invoice->lines->data[0]->period;
243	            $updates['current_period_start'] = Carbon::createFromTimestamp($period->start);
244	            $updates['current_period_end'] = Carbon::createFromTimestamp($period->end);
245	        }
246	
247	        $localSub->update($updates);
248	
249	        Log::info('Stripe invoice paid', [
250	            'subscription_id' => $localSub->id,
251	            'status' => $localSub->fresh()->status,
252	        ]);
253	    }
254	
255	    private function handleInvoicePaymentFailed(object $invoice, object $event): void
256	    {
257	        $stripeSubId = $invoice->subscription ?? null;
258	        if (! $stripeSubId) {
259	            return;
260	        }
261	
262	        $localSub = Subscription::where('stripe_subscription_id', $stripeSubId)->first();
263	        if (! $localSub) {
264	            return;
265	        }
266	
267	        $localSub->update([
268	            'status' => Subscription::STATUS_PAST_DUE,
269	            'provider_payload' => json_decode(json_encode($event), true),
270	        ]);
271	
272	        // Notify the professional about the payment failure
273	        $professional = $localSub->professional;
274	        if ($professional) {
275	            app(NotificationPublisher::class)->publish(
276	                professionalId: $professional->id,
277	                frontendType: 'warning',
278	                category: 'subscriptions',
279	                title: 'Payment failed',
