71	        // re-triggering the crashing handler. Investigate via Nightwatch if that occurs.
72	        $alreadyProcessed = ! DB::table('billing.webhook_events')->insertOrIgnore([
73	            'id' => Str::uuid()->toString(),
74	            'stripe_event_id' => $event->id,
75	            'event_type' => $event->type,
76	            'payload' => json_encode(json_decode($payload, true)),
77	            'processed_at' => now(),
78	        ]);
