87	    /**
88	     * Dispatch a verified, de-duplicated Stripe Event to the appropriate handler.
89	     * Extracted from __invoke() so it can be unit-tested without HMAC signing.
90	     *
91	     * Guards account-scoped event types by verifying the HMAC-signed top-level
92	     * `event->account` field matches `data.object->id`. A mismatch means the
93	     * payload was tampered with; we reject with 400 rather than mutating records.
94	     */
95	    public function handleParsedEvent(\Stripe\Event $event): JsonResponse
96	    {
97	        // For account-scoped events, event->account is the HMAC-signed source of truth.
98	        // If data.object.id differs, reject — payload could have been tampered with
99	        // to mutate a victim account using the attacker's valid HMAC.
100	        //
101	        // account.application.* events are excluded: their data.object is an Application
102	        // (id = ca_xxx), not an Account, so the id won't match event->account by design.
103	        $accountScopedPrefixes = ['account.', 'capability.'];
104	        $isAccountScoped = collect($accountScopedPrefixes)
105	            ->contains(fn ($p) => str_starts_with($event->type, $p));
106	
107	        if ($isAccountScoped && ! str_starts_with($event->type, 'account.application.')) {
108	            $topLevelAccount = $event->account ?? null;
109	            $objectId = $event->data->object->id ?? null;
110	
111	            if ($topLevelAccount === null || $topLevelAccount !== $objectId) {
112	                Log::warning('stripe.connect.account_mismatch', [
113	                    'event_id' => $event->id,
114	                    'event_account' => $topLevelAccount,
115	                    'object_id' => $objectId,
116	                ]);
117	
118	                return response()->json(['error' => 'account_mismatch'], 400);
119	            }
120	        }
121	
122	        match ($event->type) {
123	            'account.updated' => $this->handleAccountUpdated($event->data->object),
124	            'account.application.deauthorized' => $this->handleAccountDeauthorized((string) ($event->account ?? '')),
125	            'checkout.session.completed' => $this->handleCheckoutSessionCompleted($event->data->object, (string) ($event->account ?? '')),
