206	            // Atomic: if flushHeldCommissions throws, the status update is rolled back.
207	            // The professional stays in their prior state; the next account.updated
208	            // (new event_id, bypasses idempotency) retries the full transition cleanly.
209	            DB::transaction(function () use ($professional, $status, $oldStatus) {
210	                $professional->update(['stripe_connect_status' => $status]);
211	
212	                // When an affiliate transitions to 'active', flush any held commissions
213	                // so they enter the normal payout pipeline immediately.
214	                if ($status === 'active' && $oldStatus !== 'active') {
215	                    app(CommissionVoidService::class)->flushHeldCommissions($professional);
216	                }
217	            });
218	
219	            Log::info('Stripe Connect status updated', [
220	                'professional_id' => $professional->id,
221	                'old_status' => $oldStatus,
222	                'new_status' => $status,
223	            ]);
224	        }
225	    }
226	
227	    private function handleTransferCreated(object $transfer): void
228	    {
229	        $payoutId = $transfer->metadata?->sidest_payout_id ?? null;
230	
231	        if (! $payoutId) {
232	            return;
233	        }
234	
235	        Log::info('Stripe transfer created', [
236	            'transfer_id' => $transfer->id,
237	            'payout_id' => $payoutId,
238	        ]);
239	    }
240	
241	    private function handleTransferFailed(object $transfer): void
242	    {
243	        $payoutId = $transfer->metadata?->sidest_payout_id ?? null;
244	
245	        if (! $payoutId) {
246	            return;
247	        }
248	
249	        $payout = CommissionPayout::find($payoutId);
250	        if ($payout && ! in_array($payout->status, ['failed', 'completed', 'cancelled'], true)) {
251	            $payout->forceFill([
252	                'status' => 'failed',
253	                'failure_code' => 'transfer_failed_webhook',
254	                'failure_reason' => 'Transfer failed according to Stripe webhook',
255	            ])->save();
256	        }
257	
258	        Log::warning('Stripe transfer failed', [
259	            'transfer_id' => $transfer->id,
260	            'payout_id' => $payoutId,
261	        ]);
262	    }
263	
264	    private function handlePaymentIntentSucceeded(object $paymentIntent, string $connectedAccountId = ''): void
265	    {
266	        // Commission payout payment intent
267	        $payoutId = $paymentIntent->metadata?->sidest_payout_id ?? null;
268	        if (! $payoutId) {
269	            return;
270	        }
271	
272	        Log::info('Stripe payment intent succeeded for payout', [
273	            'payment_intent_id' => $paymentIntent->id,
274	            'payout_id' => $payoutId,
275	        ]);
276	    }
277	
278	    private function handlePaymentIntentFailed(object $paymentIntent): void
279	    {
280	        $payoutId = $paymentIntent->metadata?->sidest_payout_id ?? null;
281	
282	        if (! $payoutId) {
283	            return;
284	        }
285	
286	        $payout = CommissionPayout::find($payoutId);
287	        if ($payout && ! in_array($payout->status, ['failed', 'completed'])) {
288	            $payout->forceFill([
289	                'status' => 'failed',
290	                'failure_code' => 'payment_failed_webhook',
291	                'failure_reason' => $paymentIntent->last_payment_error?->message ?? 'Payment failed',
292	            ])->save();
293	        }
294	
295	        Log::warning('Stripe payment intent failed for payout', [
296	            'payment_intent_id' => $paymentIntent->id,
297	            'payout_id' => $payoutId,
298	        ]);
299	    }
