8	// Guards against valid-HMAC payloads that are structurally incomplete.
9	// constructEvent() validates signature + JSON parse but doesn't enforce field presence.
10	trait ValidatesStripeWebhookPayload
11	{
12	    private function validateEventStructure(Event $event): bool
13	    {
14	        $valid = ! empty($event->id)
15	            && ! empty($event->type)
16	            && $event->data !== null
17	            && ($event->data->object ?? null) !== null;
18	
19	        if (! $valid) {
20	            Log::warning('Stripe webhook rejected: missing required event fields', [
21	                'event_id' => $event->id ?? null,
22	                'event_type' => $event->type ?? null,
23	                'has_data' => $event->data !== null,
24	                'has_data_object' => ($event->data->object ?? null) !== null,
25	            ]);
26	        }
27	
28	        return $valid;
29	    }
30	}
